    // ─────────── فصل ۱: هیلشم ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "Hailsham", titlePersian = "هیلشم",
        paragraphs = listOf(
            StoryParagraph("My name is Kathy H., I am thirty-one years old, and I have been a carer for over twelve years.", "نام من کتی اچ است، سی و یک سال دارم و بیش از دوازده سال مراقب بوده‌ام."),
            StoryParagraph("I have looked after many donors over the years, and some of them have done very well, much better than anyone expected.", "در طول سال‌ها از اهداکنندگان بسیاری مراقبت کرده‌ام و بعضی‌شان خیلی خوب عمل کرده‌اند، بهتر از آنچه هر کسی انتظار داشت."),
            StoryParagraph("But that is not what I want to talk about; I want to talk about Hailsham, and about my friends, and about the things that happened to us there.", "اما این چیزی نیست که می‌خواهم درباره‌اش صحبت کنم؛ می‌خواهم درباره هیلشم صحبت کنم و درباره دوستانم و درباره چیزهایی که آنجا برایمان اتفاق افتاد."),
            StoryParagraph("Hailsham was a school, or something like a school, in the English countryside.", "هیلشم مدرسه‌ای بود، یا چیزی شبیه مدرسه، در حومه انگلیس."),
            StoryParagraph("It was a beautiful place, with green lawns and old buildings and a pond where we would watch the ducks in the afternoons.", "جای زیبایی بود، با چمن‌های سبز و ساختمان‌های قدیمی و برکه‌ای که بعدازظهرها اردک‌ها را در آن تماشا می‌کردیم."),
            StoryParagraph("We were told that we were special, that we were different from other people, that we had an important purpose in life.", "به ما گفته شد که خاص هستیم، که با دیگران متفاوتیم، که هدف مهمی در زندگی داریم."),
            StoryParagraph("We were told that we had to stay healthy, that we had to take care of our bodies, that we had to be careful about what we ate and drank.", "به ما گفته شد که باید سالم بمانیم، باید از بدن‌هایمان مراقبت کنیم، باید مراقب باشیم چه می‌خوریم و می‌نوشیم."),
            StoryParagraph("We did not fully understand what this meant; we were only children, and the adults around us spoke in a language that we did not yet know how to decode.", "کاملاً نمی‌فهمیدیم این یعنی چه؛ فقط بچه بودیم و بزرگسالان اطرافمان به زبانی صحبت می‌کردند که هنوز نمی‌دانستیم چگونه رمزگشایی کنیم."),
            StoryParagraph("There was a woman called Miss Emily, who was the head of the school, and she was a tall, stern woman with grey hair and a sharp voice.", "زنی به نام میس امیلی بود که مدیر مدرسه بود و زنی بلندقد و سختگیر با موهای خاکستری و صدایی تیز بود."),
            StoryParagraph("There was another woman called Miss Lucy, who was younger and kinder, and who sometimes told us things that she should not have told us.", "زنی دیگر به نام میس لوسی بود که جوان‌تر و مهربان‌تر بود و گاهی چیزهایی به ما می‌گفت که نباید می‌گفت."),
            StoryParagraph("My best friend was Ruth, and we did everything together; we shared our secrets, our fears, our dreams.", "بهترین دوستم راث بود و همه کارها را با هم می‌کردیم؛ رازهایمان را قسمت می‌کردیم، ترس‌هایمان، رؤیاهایمان."),
            StoryParagraph("There was also a boy named Tommy, who was quiet and gentle and who had a hard time at school.", "پسری هم به نام تامی بود که ساکت و ملایم بود و روزگار سختی در مدرسه داشت."),
            StoryParagraph("The other children teased Tommy; they called him names; they made him angry, and when he was angry, he would scream and kick and throw things.", "بچه‌های دیگر تامی را مسخره می‌کردند؛ اسم‌های زشت به او می‌گفتند؛ عصبانی‌اش می‌کردند و وقتی عصبانی می‌شد، فریاد می‌زد و لگد می‌زد و چیزها را پرت می‌کرد."),
            StoryParagraph("Miss Lucy tried to help him; she told him that it was all right to be different, that he did not have to be good at the same things as everyone else.", "میس لوسی تلاش کرد کمکش کند؛ به او گفت مشکلی نیست متفاوت باشد، لازم نیست در همان چیزهایی که بقیه‌اند خوب باشد."),
            StoryParagraph("'There will be times when you will not be able to do the things that others can do,' she said to him once, 'but that does not mean you are less than they are.'", "یک بار به او گفت: «مواقعی پیش می‌آید که نمی‌توانی کارهایی را که دیگران می‌توانند انجام دهی، اما این بدان معنا نیست که از آن‌ها کمتری.»"),
            StoryParagraph("We did not understand what she meant, not really; we thought she was just being kind to Tommy.", "نمی‌فهمیدیم منظورش چیست، نه واقعاً؛ فکر می‌کردیم فقط دارد با تامی مهربان است."),
            StoryParagraph("But now, looking back, I think she was trying to prepare us for something, something that was waiting for us all, something that we could not yet see.", "اما حالا، در نگاه به عقب، فکر می‌کنم تلاش می‌کرد آماده‌مان کند برای چیزی، چیزی که منتظر همه‌مان بود، چیزی که هنوز نمی‌توانستیم ببینیم."),
            StoryParagraph("We spent our days in lessons: art, and literature, and history, and geography, and music.", "روزهایمان را در درس‌ها می‌گذراندیم: هنر و ادبیات و تاریخ و جغرافیا و موسیقی."),
            StoryParagraph("We learned about the world outside Hailsham, the world we would one day enter, the world we would one day serve.", "درباره جهان بیرون هیلشم آموختیم، جهانی که روزی واردش می‌شدیم، جهانی که روزی خدمتش می‌کردیم."),
            StoryParagraph("But we were never told the truth, not fully, not until much later, not until it was too late to change anything.", "اما هرگز حقیقت را به ما نگفتند، نه کاملاً، نه تا مدت‌ها بعد، نه تا وقتی تغییر دادن هر چیزی خیلی دیر شده بود."),
            StoryParagraph("Art was important at Hailsham; we were told to be creative, to express ourselves, to produce things that were beautiful and unique.", "هنر در هیلشم مهم بود؛ به ما گفته شد خلاق باشیم، خودمان را بیان کنیم، چیزهایی تولید کنیم که زیبا و منحصربه‌فرد باشند."),
            StoryParagraph("We did not know why art was so important; we did not know that our drawings and paintings and poems would one day be used to prove that we had souls.", "نمی‌دانستیم چرا هنر اینقدر مهم است؛ نمی‌دانستیم که نقاشی‌ها و نوشته‌ها و شعرهایمان روزی برای اثبات اینکه روح داریم استفاده می‌شوند."),
            StoryParagraph("The Gallery was a mysterious place at Hailsham; every so often, one of our pieces would be taken away, and we would never see it again.", "گالری جایی مرموز در هیلشم بود؛ هر چند وقت یک بار، یکی از آثارمان برده می‌شد و دیگر هرگز نمی‌دیدیمش."),
            StoryParagraph("There was a woman called Madame who would come to collect the pieces; she was French, and she was strange, and she was afraid of us.", "زنی به نام مادام می‌آمد تا آثار را جمع کند؛ او فرانسوی بود و عجیب و از ما می‌ترسید."),
            StoryParagraph("We did not know why Madame was afraid of us; we did not know that she knew, that she had always known, what we were.", "نمی‌دانستیم چرا مادام از ما می‌ترسید؛ نمی‌دانستیم که او می‌دانست، که همیشه می‌دانست، ما چه هستیم."),
            StoryParagraph("We thought we were special; we thought we were the chosen ones; we thought we were lucky to be at Hailsham.", "فکر می‌کردیم خاص هستیم؛ فکر می‌کردیم برگزیدگانیم؛ فکر می‌کردیم خوش‌شانسیم که در هیلشم هستیم."),
            StoryParagraph("We did not know that we were being prepared, not for life, but for death; not for a future, but for a function.", "نمی‌دانستیم که آماده‌مان می‌کنند، نه برای زندگی، بلکه برای مرگ؛ نه برای آینده، بلکه برای وظیفه‌ای."),
            StoryParagraph("We did not know that we were clones, that we had been created from other people, that our bodies would one day be cut open and our organs harvested.", "نمی‌دانستیم که کلون هستیم، که از افراد دیگر ساخته شده‌ایم، که بدن‌هایمان روزی باز می‌شوند و اعضایمان برداشت می‌شود."),
            StoryParagraph("We did not know that we would never have children, never have families, never have lives of our own.", "نمی‌دانستیم که هرگز بچه‌دار نمی‌شویم، هرگز خانواده نمی‌سازیم، هرگز زندگی خودمان را نداریم."),
            StoryParagraph("We did not know that we would die young, after three or four donations, after our bodies had given everything they had.", "نمی‌دانستیم که جوان می‌میریم، پس از سه یا چهار اهدا، پس از اینکه بدن‌هایمان هر چه داشتند دادند."),
            StoryParagraph("We did not know any of this, not then, not in those early years, when the sun was warm and the grass was green and the ducks swam in the pond.", "هیچ‌کدام از اینها را نمی‌دانستیم، نه آن وقت، نه در آن سال‌های نخست، وقتی خورشید گرم بود و چمن سبز و اردک‌ها در برکه شنا می‌کردند."),
            StoryParagraph("We did not know, but Miss Lucy knew, and sometimes, in her weaker moments, she would try to tell us.", "نمی‌دانستیم، اما میس لوسی می‌دانست و گاهی، در لحظه‌های ضعفش، تلاش می‌کرد به ما بگوید."),
            StoryParagraph("'You are not taught enough,' she said to us one day. 'You should be told the truth. You should know what is going to happen to you.'", "یک روز به ما گفت: «به اندازه کافی به شما آموزش داده نمی‌شود. باید حقیقت به شما گفته شود. باید بدانید چه بر سرتان می‌آید.»"),
            StoryParagraph("But then Miss Emily would find out, and Miss Lucy would be disciplined, and we would be told that she had been mistaken, that she had said things she should not have said.", "اما بعد میس امیلی می‌فهمید و میس لوسی تنبیه می‌شد و به ما گفته می‌شد که اشتباه کرده، که چیزهایی گفته که نباید می‌گفت."),
            StoryParagraph("And so we continued in our ignorance, in our innocence, in our brief and beautiful childhood.", "و اینگونه در جهلمان ادامه دادیم، در معصومیت‌مان، در کودکی کوتاه و زیبایمان."),
            StoryParagraph("We did not know that this was the only childhood we would ever have, that everything that came after would be worse.", "نمی‌دانستیم که این تنها کودکی‌ای بود که هرگز داشتیم، که هر چیزی که بعد می‌آمد بدتر می‌بود."),
            StoryParagraph("We did not know that Hailsham was not a school but a prison, not a home but a factory.", "نمی‌دانستیم که هیلشم مدرسه نبود بلکه زندان بود، خانه نبود بلکه کارخانه بود."),
            StoryParagraph("We did not know that we had been made, not born; created, not conceived; manufactured, not loved.", "نمی‌دانستیم که ساخته شده بودیم، نه زاده شده؛ خلق شده، نه آبستن شده؛ تولید شده، نه دوست داشته شده."),
            StoryParagraph("We did not know any of this, not yet, not then.", "هیچ‌کدام از اینها را نمی‌دانستیم، نه هنوز، نه آن وقت.")
        )
    )

    // ─────────── فصل ۲: دوستی ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Friendship", titlePersian = "دوستی",
        paragraphs = listOf(
            StoryParagraph("Ruth and I were best friends from the very beginning; we met on our first day at Hailsham, and we never left each other's side.", "راث و من از همان آغاز بهترین دوستان بودیم؛ اولین روزمان در هیلشم همدیگر را ملاقات کردیم و هرگز از کنار هم نرفتیم."),
            StoryParagraph("She was taller than me, and stronger, and braver; she was the leader, and I was the follower, and we were both happy with that arrangement.", "او از من بلندتر بود و قوی‌تر و شجاع‌تر؛ او رهبر بود و من پیرو و هر دو از این ترتیب خوشحال بودیم."),
            StoryParagraph("We shared a dormitory, we shared our meals, we shared everything.", "خوابگاهی مشترک داشتیم، وعده‌های غذایی مشترک، همه چیز مشترک."),
            StoryParagraph("When Ruth was sad, I comforted her; when I was sad, she comforted me; when we were both sad, we sat together and said nothing, and that was enough.", "وقتی راث غمگین بود، دلداری‌اش می‌دادم؛ وقتی من غمگین بودم، او دلداری‌ام می‌داد؛ وقتی هر دو غمگین بودیم، با هم می‌نشستیم و چیزی نمی‌گفتیم و همین کافی بود."),
            StoryParagraph("Tommy was a different kind of friend; he was a boy, and he was strange, and he was angry, but there was something about him that drew me to him.", "تامی نوع دیگری از دوست بود؛ پسر بود و عجیب بود و عصبانی، اما چیزی در او بود که مرا به سمتش می‌کشید."),
            StoryParagraph("He was not like the other boys; he did not try to be tough or cool or popular; he was just himself, honestly and painfully himself.", "مثل پسرهای دیگر نبود؛ تلاش نمی‌کرد سخت یا باحال یا محبوب باشد؛ فقط خودش بود، صادقانه و به‌شکل دردناکی خودش."),
            StoryParagraph("Miss Lucy saw this in him; she saw the goodness in him, the kindness, the vulnerability that the other children could not see.", "میس لوسی این را در او دید؛ خوبی درونش را دید، مهربانی‌اش، آسیب‌پذیری‌ای که بچه‌های دیگر نمی‌دیدند."),
            StoryParagraph("'Tommy is a special boy,' she told me once. 'He is not like the others. You should be kind to him.'", "یک بار به من گفت: «تامی پسر خاصی است. مثل دیگران نیست. باید با او مهربان باشی.»"),
            StoryParagraph("I did not understand what she meant, but I tried to be kind to Tommy, and slowly, he began to trust me.", "نمی‌فهمیدم منظورش چیست اما تلاش کردم با تامی مهربان باشم و آرام‌آرام، شروع کرد به اعتماد کردن به من."),
            StoryParagraph("We would sit together in the evenings, in the corner of the common room, and we would talk about everything and nothing.", "عصرها با هم می‌نشستیم، در گوشه اتاق مشترک و درباره همه چیز و هیچ صحبت می‌کردیم."),
            StoryParagraph("'Do you ever wonder,' he asked me one night, 'what we are here for? What the point of all this is?'", "یک شب از من پرسید: «هرگز حیران شده‌ای چرا اینجاییم؟ چه فایده‌ای در همه این هست؟»"),
            StoryParagraph("'I do not know,' I said. 'I suppose we are here to learn, to grow, to become the people we are meant to be.'", "گفتم: «نمی‌دانم. گمانم اینجاییم تا بیاموزیم، رشد کنیم، کسانی شویم که قرار است باشیم.»"),
            StoryParagraph("'But what kind of people are we meant to be?' he asked. 'What are we supposed to become?'", "پرسید: «اما چه نوع کسانی قرار است باشیم؟ قرار است چه شویم؟»"),
            StoryParagraph("I did not have an answer, and so I said nothing, and we sat in silence, and the silence was comfortable and warm and safe.", "پاسخی نداشتم و بنابراین چیزی نگفتم و در سکوت نشستیم و سکوت راحت و گرم و امن بود."),
            StoryParagraph("Ruth, meanwhile, was becoming more and more interested in Tommy; she saw something in him too, something she wanted to have for herself.", "راث در همین حال، بیشتر و بیشتر به تامی علاقه‌مند می‌شد؛ او هم چیزی در تامی دید، چیزی که می‌خواست برای خودش داشته باشد."),
            StoryParagraph("'I like Tommy,' she told me one day, casually, as if it were nothing. 'I think I might love him.'", "یک روز به من گفت: «تامی را دوست دارم.» معمولی، گویی هیچ است. «فکر می‌کنم ممکن است عاشقش باشم.»"),
            StoryParagraph("My heart sank, but I did not show it; I smiled and said I was happy for her, and I meant it, or I tried to mean it.", "قلبم فرو افتاد اما نشان ندادم؛ لبخند زدم و گفتم برایش خوشحالم و منظورم بود، یا تلاش کردم منظورم باشد."),
            StoryParagraph("Ruth and Tommy became a couple; they spent their time together; they held hands and kissed and talked about a future that they did not know they would never have.", "راث و تامی زوج شدند؛ وقتشان را با هم می‌گذراندند؛ دست در دست هم می‌گذاشتند و می‌بوسیدند و درباره آینده‌ای صحبت می‌کردند که نمی‌دانستند هرگز نخواهند داشت."),
            StoryParagraph("I watched from a distance, and I felt something that I did not want to feel: jealousy.", "از دور تماشا کردم و چیزی حس کردم که نمی‌خواستم حس کنم: حسادت."),
            StoryParagraph("I did not like the feeling; it made me feel small and petty and ashamed; but I could not help it.", "این احساس را دوست نداشتم؛ احساس کوچکی و پستی و شرم می‌کردم؛ اما نمی‌توانستم جلویش را بگیرم."),
            StoryParagraph("So I turned away, and I tried to forget, and I tried to be happy for Ruth, and sometimes, I even succeeded.", "پس روی برگرداندم و تلاش کردم فراموش کنم و تلاش کردم برای راث خوشحال باشم و گاهی، حتی موفق می‌شدم."),
            StoryParagraph("But Tommy did not forget me; he would still come and find me, still sit with me, still talk to me about everything and nothing.", "اما تامی مرا فراموش نکرد؛ همچنان می‌آمد و پیدایم می‌کرد، همچنان با من می‌نشست، همچنان با من درباره همه چیز و هیچ صحبت می‌کرد."),
            StoryParagraph("Ruth noticed, and she did not like it, and she began to keep Tommy away from me, to make excuses, to find reasons.", "راث متوجه شد و دوستش نداشت و شروع کرد تامی را از من دور نگه داشتن، بهانه آوردن، دلیل یافتن."),
            StoryParagraph("And so a distance grew between the three of us, a distance that was never fully bridged, a distance that would one day tear us apart.", "و اینگونه فاصله‌ای میان ما سه نفر رشد کرد، فاصله‌ای که هرگز کاملاً پر نشد، فاصله‌ای که روزی ما را از هم می‌درید."),
            StoryParagraph("We grew older; we became teenagers; we began to understand more about the world we lived in, and less about ourselves.", "بزرگ‌تر شدیم؛ نوجوان شدیم؛ شروع کردیم به فهمیدن بیشتر درباره جهانی که در آن زندگی می‌کردیم و کمتر درباره خودمان."),
            StoryParagraph("We began to ask questions, difficult questions, questions that the teachers did not want to answer.", "شروع کردیم به پرسیدن پرسش‌ها، پرسش‌های دشوار، پرسش‌هایی که معلمان نمی‌خواستند پاسخ دهند."),
            StoryParagraph("'What is the Gallery for?' we asked. 'Why do you take our art? What happens to it?'", "پرسیدیم: «گالری برای چیست؟ چرا هنرمان را می‌برید؟ بر سرش چه می‌آید؟»"),
            StoryParagraph("'It is to show that you have souls,' Miss Emily said, and then she corrected herself. 'To show that you are human. To show that you have something inside you that is more than flesh and blood.'", "میس امیلی گفت: «برای نشان دادن این است که روح دارید.» و بعد خودش را تصحیح کرد. «برای نشان دادن اینکه انسانید. برای نشان دادن اینکه چیزی در درونتان دارید که بیش از گوشت و خوند.»"),
            StoryParagraph("We did not understand, but we did not press further; we had learned, long ago, not to press too hard.", "نفهمیدیم اما بیشتر اصرار نکردیم؛ مدت‌ها پیش یاد گرفته بودیم بیش از حد اصرار نکنیم."),
            StoryParagraph("But something had changed in us; something had awakened; something would never sleep again.", "اما چیزی در ما تغییر کرده بود؛ چیزی بیدار شده بود؛ چیزی دیگر هرگز نمی‌خوابید."),
            StoryParagraph("We began to sense the darkness at the edges of our lives, the thing that was waiting for us, the thing that no one would name.", "شروع کردیم به حس کردن تاریکی در لبه‌های زندگی‌مان، چیزی که منتظرمان بود، چیزی که هیچ‌کس نامش را نمی‌برد."),
            StoryParagraph("And so our childhood ended, as all childhoods end, but ours ended in a way that was stranger and sadder than most.", "و اینگونه کودکی‌مان تمام شد، همانطور که همه کودکی‌ها تمام می‌شوند، اما مال ما به شیوه‌ای عجیب‌تر و اندوهناک‌تر از بیشترشان تمام شد."),
            StoryParagraph("We became young adults, and we left Hailsham, and we entered the world, but not the world of normal people, not the world we had read about in books.", "بزرگسالان جوان شدیم و هیلشم را ترک کردیم و به جهان وارد شدیم، اما نه جهان آدم‌های معمولی، نه جهانی که در کتاب‌ها خوانده بودیم."),
            StoryParagraph("We entered a world that had been prepared for us, a world that had a place for us, a world that knew exactly what to do with us.", "به جهانی وارد شدیم که برایمان آماده شده بود، جهانی که جایی برایمان داشت، جهانی که دقیقاً می‌دانست با ما چه کند."),
            StoryParagraph("And we did not know it yet, but we were already walking toward our deaths.", "و هنوز نمی‌دانستیم، اما از قبل به سمت مرگ‌هایمان راه می‌رفتیم."),
            StoryParagraph("We did not know it yet, but this was the beginning of the end.", "هنوز نمی‌دانستیم، اما این آغاز پایان بود.")
        )
    )

    // ─────────── فصل ۳: حقیقت ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "The Truth", titlePersian = "حقیقت",
        paragraphs = listOf(
            StoryParagraph("The truth came to us slowly, in pieces, in fragments, like a jigsaw puzzle that we did not want to complete.", "حقیقت آهسته به ما رسید، تکه‌تکه، قطعه‌قطعه، مثل پازلی که نمی‌خواستیم کاملش کنیم."),
            StoryParagraph("The first piece came from Miss Lucy, in a moment of honesty that she would later regret.", "نخستین تکه از میس لوسی آمد، در لحظه‌ای از صداقت که بعداً پشیمانش می‌شد."),
            StoryParagraph("We were fifteen years old, and we had been asking questions about our futures, about what we would do when we left Hailsham.", "پانزده ساله بودیم و پرسش‌هایی درباره آینده‌مان پرسیده بودیم، درباره اینکه وقتی هیلشم را ترک کنیم چه می‌کنیم."),
            StoryParagraph("Miss Lucy listened to us for a while, and then, suddenly, she spoke.", "میس لوسی مدتی گوش داد و بعد، ناگهان، صحبت کرد."),
            StoryParagraph("'You will not be teachers,' she said. 'You will not be artists, or writers, or musicians. You will not grow up to be doctors, or lawyers, or anything like that.'", "گفت: «شما معلم نمی‌شوید. نه هنرمند می‌شوید، نه نویسنده، نه نوازنده. بزرگ نمی‌شوید که دکتر شوید، یا وکیل، یا چیزی شبیه آن.»"),
            StoryParagraph("'Then what will we be?' Ruth asked, and her voice was small and afraid.", "راث پرسید: «پس چه می‌شویم؟» و صدایش کوچک و ترسیده بود."),
            StoryParagraph("'You will be donors,' Miss Lucy said. 'Your whole lives have been shaped for that. When you are old enough, you will begin to donate your organs.'", "میس لوسی گفت: «اهداکننده می‌شوید. تمام زندگی‌تان برای این شکل گرفته. وقتی به اندازه کافی بزرگ شدید، شروع می‌کنید به اهدای اعضایتان.»"),
            StoryParagraph("'Donate?' I said. 'What do you mean, donate?'", "گفتم: «اهدای؟ منظورتان از اهدا چیست؟»"),
            StoryParagraph("'Your kidneys, your liver, your heart, your lungs — anything that can be used, anything that can save a life.'", "«کلیه‌هایتان، کبدتان، قلبتان، ریه‌هایتان — هر چیزی که بتوان استفاده کرد، هر چیزی که بتواند جان کسی را نجات دهد.»"),
            StoryParagraph("'But why?' Tommy asked. 'Why us?'", "تامی پرسید: «اما چرا؟ چرا ما؟»"),
            StoryParagraph("Miss Lucy looked at him for a long moment, and there was something in her eyes that I had never seen before: sorrow, deep and endless sorrow.", "میس لوسی مدت طولانی نگاهش کرد و چیزی در چشمانش بود که هرگز قبلاً ندیده بودم: اندوه، اندوه عمیق و بی‌پایان."),
            StoryParagraph("'Because you were made for it,' she said. 'You were created for this purpose. You are not like other people. You are... different.'", "گفت: «چون برای این ساخته شده‌اید. برای این هدف خلق شده‌اید. مثل دیگران نیستید. شما... متفاوتید.»"),
            StoryParagraph("'Different how?' Ruth asked, and her voice was shaking.", "راث پرسید: «چطور متفاوت؟» و صدایش می‌لرزید."),
            StoryParagraph("'You are clones,' Miss Lucy said, and the word fell into the room like a stone into water. 'You were created from other people, from donors. You are copies.'", "میس لوسی گفت: «شما کلون هستید.» و کلمه مثل سنگی در آب در اتاق افتاد. «از افراد دیگر ساخته شده‌اید، از اهداکنندگان. کپی هستید.»"),
            StoryParagraph("We sat in silence, all of us, and no one spoke, and no one moved, and the world seemed to stop.", "در سکوت نشستیم، همه‌مان و هیچ‌کس صحبت نکرد و هیچ‌کس تکان نخورد و جهان به نظر ایستاد."),
            StoryParagraph("'And when we are done donating?' Ruth asked, at last.", "راث سرانجام پرسید: «و وقتی اهدا کردن را تمام کردیم؟»"),
            StoryParagraph("'You complete,' Miss Lucy said. 'That is the word we use. You complete.'", "میس لوسی گفت: «تمام می‌شوید. این کلمه‌ای است که استفاده می‌کنیم. تمام می‌شوید.»"),
            StoryParagraph("'And what happens then?' I asked.", "پرسیدم: «و بعد چه اتفاقی می‌افتد؟»"),
            StoryParagraph("'You die,' Miss Lucy said. 'After three or four donations, your body can no longer sustain itself. You die.'", "میس لوسی گفت: «می‌میرید. بعد از سه یا چهار اهدا، بدن‌تان دیگر نمی‌تواند خودش را نگه دارد. می‌میرید.»"),
            StoryParagraph("Ruth began to cry, silently, and Tommy held her hand, and I sat there, frozen, unable to move, unable to speak.", "راث بی‌صدا شروع به گریه کرد و تامی دستش را گرفت و من آنجا نشستم، منجمد، ناتوان از حرکت، ناتوان از صحبت."),
            StoryParagraph("'You should not have told them,' Miss Emily said later, when she found out. 'They are not ready. They are too young.'", "میس امیلی بعداً وقتی فهمید گفت: «نباید به آن‌ها می‌گفتی. آماده نیستند. خیلی جوانند.»"),
            StoryParagraph("'They deserve to know,' Miss Lucy said. 'They deserve the truth.'", "میس لوسی گفت: «سزاوار دانستن هستند. سزاوار حقیقت هستند.»"),
            StoryParagraph("'The truth will destroy them,' Miss Emily said. 'The truth will make them unable to fulfill their purpose.'", "میس امیلی گفت: «حقیقت نابودشان می‌کند. حقیقت آن‌ها را ناتوان از انجام وظیفه‌شان می‌کند.»"),
            StoryParagraph("Miss Lucy was dismissed soon after; she left Hailsham, and we never saw her again.", "میس لوسی به‌زودی اخراج شد؛ هیلشم را ترک کرد و دیگر هرگز ندیدیمش."),
            StoryParagraph("But her words stayed with us; her words changed us; her words could never be forgotten.", "اما کلماتش با ما ماندند؛ کلماتش تغییرمان دادند؛ کلماتش هرگز فراموش نمی‌شدند."),
            StoryParagraph("We knew now what we were; we knew now what would happen to us; we knew now that our lives were not our own.", "حالا می‌دانستیم چه هستیم؛ حالا می‌دانستیم چه بر سرمان می‌آید؛ حالا می‌دانستیم که زندگی‌هایمان مال خودمان نبود."),
            StoryParagraph("And yet, we did not rebel; we did not run away; we did not fight.", "و با این حال، شورش نکردیم؛ فرار نکردیم؛ نجنگیدیم."),
            StoryParagraph("We had been conditioned, all our lives, to accept; we had been taught, all our lives, that this was our purpose.", "تمام زندگی‌مان شرطی شده بودیم که بپذیریم؛ تمام زندگی‌مان یاد گرفته بودیم که این هدفمان است."),
            StoryParagraph("We were like animals that had been raised for slaughter; we did not know how to be anything else.", "مثل حیواناتی بودیم که برای ذبح بزرگ شده بودند؛ نمی‌دانستیم چطور چیز دیگری باشیم."),
            StoryParagraph("Ruth took it hardest; she became angry, and then bitter, and then resigned.", "راث سخت‌ترین ضربه را خورد؛ عصبانی شد و بعد تلخ و بعد تسلیم."),
            StoryParagraph("Tommy took it quietly; he had always known, somehow, that he was different; the truth only confirmed what he had already suspected.", "تامی آرام گرفت؛ همیشه به نوعی می‌دانست که متفاوت است؛ حقیقت فقط آنچه را که از قبل گمان می‌کرد تأیید کرد."),
            StoryParagraph("And I — I did not know how to feel; I did not know what to think; I did not know anything anymore.", "و من — نمی‌دانستم چه حس کنم؛ نمی‌دانستم چه فکر کنم؛ دیگر هیچ چیز نمی‌دانستم."),
            StoryParagraph("I only knew that everything had changed, that nothing would ever be the same, that the world was not what I had thought it was.", "تنها می‌دانستم همه چیز تغییر کرده، هیچ چیز هرگز همان نمی‌شود، جهان آن چیزی نبود که فکر می‌کردم."),
            StoryParagraph("We left Hailsham not long after; we were eighteen, and it was time for us to move on.", "چند وقت بعد هیلشم را ترک کردیم؛ هجده ساله بودیم و وقتش بود به جلو برویم."),
            StoryParagraph("We went to the Cottages, a place where we were supposed to learn how to be adults, how to be independent, how to be donors.", "به کلبه‌ها رفتیم، جایی که قرار بود یاد بگیریم چگونه بزرگسال باشیم، چگونه مستقل باشیم، چگونه اهداکننده باشیم."),
            StoryParagraph("But we had already learned the most important thing of all: that we were going to die.", "اما مهم‌ترین چیز از همه را از قبل آموخته بودیم: که می‌خواهیم بمیریم."),
            StoryParagraph("And now we had to learn how to live with that knowledge.", "و حالا باید یاد می‌گرفتیم با آن دانش زندگی کنیم."),
            StoryParagraph("It was not easy, and we did not always succeed, but we tried, because there was nothing else to do.", "آسان نبود و همیشه موفق نمی‌شدیم اما تلاش کردیم، چون کار دیگری نبود."),
            StoryParagraph("We tried, because we were alive, and being alive means trying, even when there is no hope.", "تلاش کردیم، چون زنده بودیم و زنده بودن یعنی تلاش کردن، حتی وقتی امیدی نیست.")
        )
    )

    // ─────────── فصل ۴: کلبه‌ها ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The Cottages", titlePersian = "کلبه‌ها",
        paragraphs = listOf(
            StoryParagraph("The Cottages were a collection of old farm buildings in the countryside, miles from anywhere, surrounded by fields and woods.", "کلبه‌ها مجموعه‌ای از ساختمان‌های کشاورزی قدیمی در حومه بودند، مایل‌ها دور از هر جایی، احاطه‌شده با مزارع و جنگل‌ها."),
            StoryParagraph("We lived there with other donors from other schools, from other parts of the country, from other lives.", "آنجا با اهداکنندگان دیگر از مدارس دیگر زندگی می‌کردیم، از بخش‌های دیگر کشور، از زندگی‌های دیگر."),
            StoryParagraph("We had more freedom than we had had at Hailsham, but we did not know what to do with it.", "آزادی بیشتری از هیلشم داشتیم اما نمی‌دانستیم با آن چه کنیم."),
            StoryParagraph("We had been trained, all our lives, to follow rules, to obey authority, to do what we were told.", "تمام زندگی‌مان آموزش دیده بودیم که از قوانین پیروی کنیم، از قدرت اطاعت کنیم، آنچه به ما گفته می‌شود انجام دهیم."),
            StoryParagraph("And now, suddenly, we were free, and we did not know how to be free.", "و حالا، ناگهان، آزاد بودیم و نمی‌دانستیم چطور آزاد باشیم."),
            StoryParagraph("There were rumors at the Cottages, rumors about a deferral, a way to postpone our donations.", "شایعاتی در کلبه‌ها بود، شایعاتی درباره تعویق، راهی برای به تأخیر انداختن اهداهایمان."),
            StoryParagraph("'If two donors are truly in love,' the rumor said, 'they can ask for a deferral. They can have a few more years together before they have to start donating.'", "شایعه می‌گفت: «اگر دو اهداکننده واقعاً عاشق هم باشند، می‌توانند تعویق بخواهند. می‌توانند چند سال بیشتر با هم داشته باشند پیش از اینکه مجبور شوند شروع به اهدا کنند.»"),
            StoryParagraph("We did not know if the rumor was true, but we wanted to believe it; we needed to believe it.", "نمی‌دانستیم شایعه درست است یا نه، اما می‌خواستیم باورش کنیم؛ نیاز داشتیم باورش کنیم."),
            StoryParagraph("Ruth, Tommy, and I went to the Cottages together; we stayed together, as we had always stayed together.", "راث، تامی و من با هم به کلبه‌ها رفتیم؛ با هم ماندیم، همانطور که همیشه با هم مانده بودیم."),
            StoryParagraph("But we were not the same as we had been; the truth had changed us, as it changes everyone, and we could not go back.", "اما همان نبودیم که بودیم؛ حقیقت تغییرمان داده بود، همانطور که همه را تغییر می‌دهد و نمی‌توانستیم بازگردیم."),
            StoryParagraph("Ruth and Tommy were still together, but their relationship was strained; they argued more, and laughed less, and the love between them seemed to be fading.", "راث و تامی هنوز با هم بودند اما رابطه‌شان پرتنش بود؛ بیشتر بحث می‌کردند و کمتر می‌خندیدند و عشق میانشان به نظر محو می‌شد."),
            StoryParagraph("I watched them, and I said nothing, and I thought about what might have been.", "تماشایشان کردم و چیزی نگفتم و به آنچه می‌توانست باشد فکر کردم."),
            StoryParagraph("'You still love him, don't you?' Ruth said to me one night, and there was no anger in her voice, only sadness.", "راث یک شب به من گفت: «هنوز دوستش داری، نه؟» و در صدایش خشمی نبود، تنها اندوه."),
            StoryParagraph("'I do not know,' I said, and it was the truth, or as close to the truth as I could come.", "گفتم: «نمی‌دانم.» و حقیقت بود، یا تا جایی که می‌توانستم به حقیقت برسم."),
            StoryParagraph("'I know,' she said. 'I have always known. I have always known that he loved you more than he loved me.'", "گفت: «می‌دانم. همیشه می‌دانستم. همیشه می‌دانستم که او تو را بیشتر از من دوست داشت.»"),
            StoryParagraph("'That is not true,' I said, but she shook her head.", "گفتم: «این درست نیست.» اما سرش را تکان داد."),
            StoryParagraph("'It is true,' she said. 'And I have been punishing you for it, all these years. I have been keeping you apart. I have been cruel.'", "گفت: «درست است. و تمام این سال‌ها برایش مجازاتت کرده‌ام. دور نگهتان داشته‌ام. بی‌رحم بوده‌ام.»"),
            StoryParagraph("'Why?' I asked.", "پرسیدم: «چرا؟»"),
            StoryParagraph("'Because I was afraid,' she said. 'Because I did not want to be alone. Because I knew that if he had a choice, he would choose you, and I could not bear that.'", "گفت: «چون می‌ترسیدم. چون نمی‌خواستم تنها باشم. چون می‌دانستم اگر او انتخابی داشت، تو را برمی‌گزید و نمی‌توانستم تحملش کنم.»"),
            StoryParagraph("I did not know what to say; I had never heard Ruth speak so honestly, so openly, so vulnerably.", "نمی‌دانستم چه بگویم؛ هرگز ندیده بودم راث اینقدر صادقانه صحبت کند، اینقدر باز، اینقدر آسیب‌پذیر."),
            StoryParagraph("'I am sorry,' she said. 'I am sorry for everything.'", "گفت: «متأسفم. برای همه چیز متأسفم.»"),
            StoryParagraph("And then she did something that surprised me: she took my hand, and she held it, and she did not let go.", "و بعد کاری کرد که حیرت‌زده‌ام کرد: دستم را گرفت و نگهش داشت و رهایش نکرد."),
            StoryParagraph("'Promise me something,' she said. 'Promise me that when I am gone, you will be with Tommy. Promise me that you will not waste any more time.'", "گفت: «قولی به من بده. قول بده وقتی رفتم، با تامی خواهی بود. قول بده بیشتر از این وقت هدر نمی‌دهی.»"),
            StoryParagraph("'You are not going anywhere,' I said.", "گفتم: «تو جایی نمی‌روی.»"),
            StoryParagraph("'We are all going somewhere,' she said. 'We are all going to the same place. The only question is when.'", "گفت: «همه‌مان جایی می‌رویم. همه به همان جا می‌رویم. تنها پرسش این است که کِی.»"),
            StoryParagraph("I promised her, and she smiled, and for a moment, we were children again, at Hailsham, before we knew anything, before everything changed.", "قولش را دادم و لبخند زد و لحظه‌ای، دوباره بچه بودیم، در هیلشم، پیش از اینکه چیزی بدانیم، پیش از اینکه همه چیز تغییر کند."),
            StoryParagraph("Ruth began donating a few months later; she was one of the first of our group to start, and she was not ready.", "راث چند ماه بعد شروع به اهدا کرد؛ او یکی از نخستین‌های گروه ما بود که شروع کرد و آماده نبود."),
            StoryParagraph("She had her first donation, and then her second, and after the second, she became weak, and tired, and she could not do the things she used to do.", "نخستین اهدایش را کرد و بعد دومی و بعد از دومی، ضعیف شد و خسته و نمی‌توانست کارهایی که قبلاً می‌کرد انجام دهد."),
            StoryParagraph("Tommy and I visited her often, at the recovery center, where she was staying between donations.", "تامی و من زیاد به دیدنش می‌رفتیم، در مرکز بهبودی، جایی که بین اهداها می‌ماند."),
            StoryParagraph("She grew thin, and pale, and her eyes lost their light; she was dying, and we all knew it.", "لاغر شد و رنگ‌پریده و چشمانش نورش را از دست داد؛ او در حال مرگ بود و همه می‌دانستیم."),
            StoryParagraph("'I am not afraid,' she told me once, when Tommy had gone to get coffee. 'I have been afraid all my life, and now, I am not afraid.'", "یک بار وقتی تامی رفته بود قهوه بیاورد به من گفت: «نمی‌ترسم. تمام عمرم ترسیده بودم و حالا، نمی‌ترسم.»"),
            StoryParagraph("'Why not?' I asked.", "پرسیدم: «چرا نه؟»"),
            StoryParagraph("'Because I have finally understood something,' she said. 'I have understood that it does not matter how long we live. What matters is how we live.'", "گفت: «چون سرانجام چیزی را فهمیدم. فهمیدم مهم نیست چقدر زندگی می‌کنیم. آنچه مهم است این است که چگونه زندگی می‌کنیم.»"),
            StoryParagraph("'And how should we live?' I asked.", "پرسیدم: «و چگونه باید زندگی کنیم؟»"),
            StoryParagraph("'With love,' she said. 'With kindness. With honesty. With the courage to be who we really are, even when the world wants us to be something else.'", "گفت: «با عشق. با مهربانی. با صداقت. با شجاعت اینکه آنکه واقعاً هستیم باشیم، حتی وقتی جهان می‌خواهد چیز دیگری باشیم.»"),
            StoryParagraph("She died a few days later, after her third donation, and Tommy and I were with her at the end.", "چند روز بعد، پس از اهدای سومش مرد و تامی و من در پایان با او بودیم."),
            StoryParagraph("'Be happy,' she whispered, and she looked at us, one last time, and then she was gone.", "زمزمه کرد: «خوشحال باشید.» و یک بار آخر نگاهمان کرد و بعد رفت."),
            StoryParagraph("And Tommy and I held each other, and we wept, and we knew that we had lost a part of ourselves, a part that could never be replaced.", "و تامی و من هم را در آغوش گرفتیم و گریه کردیم و می‌دانستیم بخشی از خودمان را از دست داده‌ایم، بخشی که هرگز نمی‌شد جایگزینش کرد."),
            StoryParagraph("But we also knew that Ruth had given us a gift, a gift that we would carry with us forever: the gift of her honesty, of her courage, of her love.", "اما همچنین می‌دانستیم راث هدیه‌ای به ما داده بود، هدیه‌ای که برای همیشه با خود حمل می‌کردیم: هدیه صداقتش، شجاعتش، عشقش."),
            StoryParagraph("And we knew, at last, that we were free — free to love each other, free to be together, free to live the few years we had left.", "و سرانجام می‌دانستیم که آزاد بودیم — آزاد برای دوست داشتن یکدیگر، آزاد برای با هم بودن، آزاد برای زندگی کردن آن چند سالی که باقی مانده بود."),
            StoryParagraph("And so, after all those years, after all that time, we finally found our way to each other.", "و اینگونه، پس از تمام آن سال‌ها، پس از تمام آن وقت، سرانجام راهمان را به سوی هم یافتیم."),
            StoryParagraph("It was later than we had hoped, but it was not too late; and that, perhaps, was enough.", "دیرتر از آنچه امید داشتیم بود، اما خیلی دیر نبود؛ و این، شاید، کافی بود.")
        )
    )

    // ─────────── فصل ۵: پایان ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The End", titlePersian = "پایان",
        paragraphs = listOf(
            StoryParagraph("After Ruth died, Tommy and I became inseparable; we spent every moment we could together, as if we were trying to make up for lost time.", "بعد از مرگ راث، تامی و من از هم جدا نشدیم؛ هر لحظه‌ای که می‌توانستیم با هم می‌گذراندیم، گویی تلاش می‌کردیم برای وقت از دست رفته جبران کنیم."),
            StoryParagraph("We talked about the past, about Hailsham, about Ruth, about all the years we had wasted.", "درباره گذشته صحبت کردیم، درباره هیلشم، درباره راث، درباره تمام سال‌هایی که هدر داده بودیم."),
            StoryParagraph("'I should have chosen you,' Tommy said one night. 'All those years ago, I should have chosen you.'", "تامی یک شب گفت: «باید تو را انتخاب می‌کردم. تمام آن سال‌ها پیش، باید تو را انتخاب می‌کردم.»"),
            StoryParagraph("'It does not matter now,' I said.", "گفتم: «حالا مهم نیست.»"),
            StoryParagraph("'It does matter,' he said. 'It matters because we have so little time left. It matters because every moment counts.'", "گفت: «مهم است. مهم است چون وقت کمی برایمان مانده. مهم است چون هر لحظه اهمیت دارد.»"),
            StoryParagraph("He was right, of course; he was always right about the important things.", "البته که حق داشت؛ همیشه در چیزهای مهم حق داشت."),
            StoryParagraph("We decided to apply for a deferral; we had heard the rumors, and we wanted to believe them, and we wanted to try.", "تصمیم گرفتیم برای تعویق درخواست دهیم؛ شایعات را شنیده بودیم و می‌خواستیم باورشان کنیم و می‌خواستیم تلاش کنیم."),
            StoryParagraph("We found out where Madame lived; she had been the one who collected our art, at Hailsham, and we believed she would help us.", "فهمیدیم مادام کجا زندگی می‌کند؛ او کسی بود که هنرمان را در هیلشم جمع می‌کرد و باور داشتیم کمکمان می‌کند."),
            StoryParagraph("We traveled to her address, a small house on the edge of a town, and we knocked on the door.", "به آدرسش سفر کردیم، خانه‌ای کوچک در حاشیه شهری و در را زدیم."),
            StoryParagraph("She opened it, and when she saw us, her face went pale, and she took a step back.", "بازش کرد و وقتی ما را دید، صورتش رنگ‌پریده شد و قدمی عقب رفت."),
            StoryParagraph("'I know you,' she said. 'You are from Hailsham.'", "گفت: «می‌شناسمتان. از هیلشامید.»"),
            StoryParagraph("'We need your help,' Tommy said. 'We want to apply for a deferral.'", "تامی گفت: «به کمکتان نیاز داریم. می‌خواهیم برای تعویق درخواست دهیم.»"),
            StoryParagraph("Madame looked at us, and there was something in her eyes that I could not name: pity, perhaps, or sorrow, or fear.", "مادام نگاهمان کرد و چیزی در چشمانش بود که نمی‌توانستم نامش را ببرم: ترحم، شاید، یا اندوه، یا ترس."),
            StoryParagraph("'A deferral,' she said. 'Is that what you think exists?'", "گفت: «تعویق. فکر می‌کنید وجود دارد؟»"),
            StoryParagraph("'Is it not true?' I asked.", "پرسیدم: «درست نیست؟»"),
            StoryParagraph("She did not answer; she simply stepped aside and let us enter.", "پاسخ نداد؛ تنها کنار رفت و گذاشت وارد شویم."),
            StoryParagraph("Inside, there was another person waiting for us: Miss Emily, the head of Hailsham, now old and frail and sitting in a wheelchair.", "داخل، شخص دیگری منتظرمان بود: میس امیلی، مدیر هیلشم، حالا پیر و نحیف و روی ویلچری نشسته."),
            StoryParagraph("'I thought you might come,' Miss Emily said. 'Eventually, they always come.'", "میس امیلی گفت: «فکر می‌کردم ممکن است بیایید. در نهایت، همیشه می‌آیند.»"),
            StoryParagraph("'Is the deferral real?' Tommy asked, and his voice was desperate, almost pleading.", "تامی پرسید: «تعویق واقعی است؟» و صدایش ناامید بود، تقریباً التماس‌آمیز."),
            StoryParagraph("Miss Emily looked at him for a long time, and there was something in her face that I had never seen before: sorrow, deep and ancient sorrow.", "میس امیلی مدت طولانی نگاهش کرد و چیزی در صورتش بود که هرگز قبلاً ندیده بودم: اندوه، اندوه عمیق و کهن."),
            StoryParagraph("'There is no deferral,' she said, at last. 'There never was.'", "سرانجام گفت: «تعویقی وجود ندارد. هرگز نداشته.»"),
            StoryParagraph("'But we heard—' I began.", "شروع کردم: «اما شنیدیم—»"),
            StoryParagraph("'You heard a rumor,' Miss Emily said. 'A rumor that we allowed to spread, because it gave you hope, and hope kept you alive.'", "میس امیلی گفت: «شایعه‌ای شنیدید. شایعه‌ای که گذاشتیم پخش شود، چون به شما امید می‌داد و امید شما را زنده نگه می‌داشت.»"),
            StoryParagraph("'So it was a lie?' Tommy said, and his voice was hollow.", "تامی گفت: «پس دروغ بود؟» و صدایش توخالی بود."),
            StoryParagraph("'Not a lie,' Miss Emily said. 'A kindness. A mercy.'", "میس امیلی گفت: «دروغ نه. مهربانی. رحم.»"),
            StoryParagraph("'How can a lie be a kindness?' I asked.", "پرسیدم: «چطور دروغ می‌تواند مهربانی باشد؟»"),
            StoryParagraph("'Because the truth,' Miss Emily said, 'would have destroyed you. The truth is too terrible to bear.'", "میس امیلی گفت: «چون حقیقت نابودتان می‌کرد. حقیقت بسیار هولناک است که تحمل شود.»"),
            StoryParagraph("And then she told us everything: about the donations, about the completion, about the fact that we would never live beyond our thirties.", "و بعد همه چیز را برایمان گفت: درباره اهداها، درباره تکمیل، درباره اینکه هرگز بیش از سی سالگی زندگی نمی‌کنیم."),
            StoryParagraph("She told us about Hailsham, about the Gallery, about why our art had been collected.", "درباره هیلشم گفت، درباره گالری، درباره اینکه چرا هنرمان جمع‌آوری شده بود."),
            StoryParagraph("'We wanted to prove that you had souls,' she said. 'That you were not just bodies, not just machines. We wanted to show the world that you were human.'", "گفت: «می‌خواستیم ثابت کنیم روح دارید. که فقط بدن نیستید، فقط ماشین نیستید. می‌خواستیم به جهان نشان دهیم که انسانید.»"),
            StoryParagraph("'And did you succeed?' I asked.", "پرسیدم: «و موفق شدید؟»"),
            StoryParagraph("'For a time,' she said. 'But then the world moved on. The world did not want to be reminded of what you were, of what we had created. The world wanted to forget.'", "گفت: «برای مدتی. اما بعد جهان ادامه یافت. جهان نمی‌خواست یادآوری شود که شما چه بودید، که ما چه ساخته بودیم. جهان می‌خواست فراموش کند.»"),
            StoryParagraph("'So we were created to die,' Tommy said. 'We were created to be used, and then discarded.'", "تامی گفت: «پس ما برای مردن ساخته شدیم. برای استفاده شدن ساخته شدیم و بعد دور انداخته شدن.»"),
            StoryParagraph("'Yes,' Miss Emily said. 'That is the truth. That has always been the truth.'", "میس امیلی گفت: «بله. این حقیقت است. همیشه این حقیقت بوده.»"),
            StoryParagraph("We left the house in silence, and we walked through the town, and we did not speak, because there was nothing to say.", "خانه را در سکوت ترک کردیم و در شهر قدم زدیم و صحبت نکردیم، چون چیزی برای گفتن نبود."),
            StoryParagraph("Everything we had believed had been a lie; everything we had hoped for had been an illusion; everything we had lived for had been meaningless.", "هر چیزی که باور کرده بودیم دروغ بود؛ هر چیزی که امیدوار بودیم توهم بود؛ هر چیزی که برایش زندگی کرده بودیم بی‌معنا بود."),
            StoryParagraph("And yet, we were still alive; we were still together; we still had each other.", "و با این حال، هنوز زنده بودیم؛ هنوز با هم بودیم؛ هنوز یکدیگر را داشتیم."),
            StoryParagraph("'What do we do now?' Tommy asked.", "تامی پرسید: «حالا چه می‌کنیم؟»"),
            StoryParagraph("'We live,' I said. 'We live as much as we can, for as long as we can.'", "گفتم: «زندگی می‌کنیم. تا جایی که می‌توانیم زندگی می‌کنیم، تا زمانی که می‌توانیم.»"),
            StoryParagraph("And so we did; we lived, and we loved, and we were together, and we were happy, as much as anyone can be happy in such a world.", "و اینگونه کردیم؛ زندگی کردیم و عشق ورزیدیم و با هم بودیم و خوشحال بودیم، تا جایی که کسی می‌تواند در چنین جهانی خوشحال باشد."),
            StoryParagraph("We had two years together, two beautiful years, and they were the best years of my life.", "دو سال با هم داشتیم، دو سال زیبا و بهترین سال‌های زندگی‌ام بودند."),
            StoryParagraph("Tommy started donating, and then, after his second donation, he began to weaken, and after his third, he could not go on.", "تامی شروع به اهدا کرد و بعد از اهدای دومش شروع به ضعیف شدن کرد و بعد از سومی، نتوانست ادامه دهد."),
            StoryParagraph("He completed, as they say, in a small hospital, with me by his side.", "تکمیل کرد، همانطور که می‌گویند، در بیمارستانی کوچک، با من در کنارش."),
            StoryParagraph("'I am not afraid,' he said, as the end came. 'I have loved you. I have been loved. That is enough.'", "گفت: «نمی‌ترسم.» همانطور که پایان می‌آمد. «تو را دوست داشته‌ام. دوست داشته شده‌ام. همین کافی است.»"),
            StoryParagraph("And then he was gone, and I was alone, and the world went on, as it always does, indifferent to our pain.", "و بعد رفت و من تنها شدم و جهان ادامه یافت، همانطور که همیشه می‌کند، بی‌تفاوت به دردمان.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("Never Let Me Go, published in 2005, is one of the most haunting novels of the twenty-first century, and its meaning deepens with every reading.", "هرگز رهایم مکن، منتشرشده در ۲۰۰۵، یکی از آشفته‌کننده‌ترین رمان‌های قرن بیست و یکم است و معنایش با هر خوانش عمیق‌تر می‌شود."),
            StoryParagraph("It is, on the surface, a novel about clones, about a dystopian future, about the ethics of biotechnology.", "در سطح، رمانی است درباره کلون‌ها، درباره آینده‌ای دیستوپیایی، درباره اخلاقیات زیست‌فناوری."),
            StoryParagraph("But it is, at a deeper level, a novel about love, and loss, and the meaning of life in the face of death.", "اما در سطح عمیق‌تر، رمانی است درباره عشق و فقدان و معنای زندگی در رویارویی با مرگ."),
            StoryParagraph("Kathy, Tommy, and Ruth are not so different from us; they love, they hope, they suffer, they die.", "کتی، تامی و راث چندان با ما متفاوت نیستند؛ عشق می‌ورزند، امید دارند، رنج می‌کشند، می‌میرند."),
            StoryParagraph("The only difference is that they know when they are going to die; they know their lives will be short; they know their purpose is to give, not to receive.", "تنها تفاوت این است که می‌دانند کِی می‌میرند؛ می‌دانند زندگی‌شان کوتاه است؛ می‌دانند هدفشان دادن است، نه گرفتن."),
            StoryParagraph("And yet, in the face of this knowledge, they do not despair; they live, they love, they create meaning in the little time they have.", "و با این حال، در رویارویی با این دانش، ناامید نمی‌شوند؛ زندگی می‌کنند، عشق می‌ورزند، معنا می‌آفرینند در آن زمان اندکی که دارند."),
            StoryParagraph("This is what makes the novel so powerful; it shows us that meaning is not given, but created; not found, but made.", "این همان چیزی است که رمان را اینقدر قدرتمند می‌کند؛ نشانمان می‌دهد معنا داده نمی‌شود، بلکه آفریده می‌شود؛ یافته نمی‌شود، بلکه ساخته می‌شود."),
            StoryParagraph("Kathy is the narrator, and she tells her story in a quiet, understated voice, full of grief and acceptance.", "کتی راوی است و داستانش را با صدایی آرام و کم‌گو تعریف می‌کند، پر از اندوه و پذیرش."),
            StoryParagraph("She does not rage against her fate; she does not rebel against the system that created her; she simply tells her story, honestly, fully, without self-pity.", "علیه سرنوشتش خشم نمی‌کند؛ علیه نظامی که او را ساخته شورش نمی‌کند؛ تنها داستانش را تعریف می‌کند، صادقانه، کاملاً، بدون خودترحمی."),
            StoryParagraph("And in that telling, in that quiet dignity, there is something profoundly human, something that transcends the horror of her situation.", "و در آن تعریف، در آن وقار آرام، چیزی عمیقاً انسانی هست، چیزی که از هولناکی موقعیتش فراتر می‌رود."),
            StoryParagraph("Ishiguro wrote the novel after the birth of his own child, and it is, in many ways, a meditation on what it means to be a parent, to love a child, to face the pain of letting go.", "ایشی‌گورو رمان را پس از تولد فرزند خودش نوشت و به شیوه‌های بسیاری، مراقبه‌ای است درباره اینکه پدر و مادر بودن یعنی چه، دوست داشتن بچه، رویارویی با درد رها کردن."),
            StoryParagraph("But it is also a meditation on what it means to be human, to be mortal, to live in the knowledge that death is coming.", "اما همچنین مراقبه‌ای است درباره اینکه انسان بودن یعنی چه، فانی بودن، زندگی کردن با دانش اینکه مرگ می‌آید."),
            StoryParagraph("We are all, in a sense, like Kathy and Tommy; we are all going to die; we all have limited time; we must all make meaning in the face of that limit.", "همه‌مان به نوعی مانند کتی و تامی هستیم؛ همه‌مان می‌میریم؛ همه‌مان وقت محدودی داریم؛ همه‌مان باید در رویارویی با آن محدودیت معنا بسازیم."),
            StoryParagraph("The novel asks us: how should we live, knowing that we will die?", "رمان از ما می‌پرسد: چگونه باید زندگی کنیم، با دانستن اینکه می‌میریم؟"),
            StoryParagraph("And it answers: with love, with kindness, with honesty, with courage.", "و پاسخ می‌دهد: با عشق، با مهربانی، با صداقت، با شجاعت."),
            StoryParagraph("With the willingness to be vulnerable, to let others in, to risk the pain of loss for the sake of love.", "با آمادگی آسیب‌پذیر بودن، گذاشتن دیگران وارد شوند، به خطر انداختن درد فقدان به خاطر عشق."),
            StoryParagraph("With the acceptance that our lives may be short, but that they can still be full, still be meaningful, still be beautiful.", "با پذیرش اینکه زندگی‌هایمان ممکن است کوتاه باشد، اما هنوز می‌تواند پر باشد، هنوز معنادار، هنوز زیبا."),
            StoryParagraph("The novel ends with Kathy standing by a fence, looking out at the fields, remembering the past.", "رمان با کتی در کنار حصاری پایان می‌یابد، نگاه به مزارع، به یاد آوردن گذشته."),
            StoryParagraph("She is alone now; Tommy is dead; Ruth is dead; everyone she loved is gone.", "او حالا تنهاست؛ تامی مرده؛ راث مرده؛ همه کسانی که دوست داشت رفته‌اند."),
            StoryParagraph("But she does not despair; she remembers, and in remembering, she keeps them alive.", "اما ناامید نمی‌شود؛ به یاد می‌آورد و در یادآوردن، زنده‌شان نگه می‌دارد."),
            StoryParagraph("'I was thinking,' she says, 'about the time when we were children at Hailsham, and how we used to imagine our futures.'", "می‌گوید: «فکر می‌کردم درباره زمانی که در هیلشم بچه بودیم و چگونه آینده‌مان را تصور می‌کردیم.»"),
            StoryParagraph("'None of us imagined the futures we actually had,' she says. 'We imagined lives of freedom, of adventure, of ordinary happiness.'", "می‌گوید: «هیچ‌کدام آینده‌ای را که واقعاً داشتیم تصور نمی‌کردیم. زندگی‌هایی از آزادی تصور می‌کردیم، از ماجراجویی، از خوشبختی معمولی.»"),
            StoryParagraph("'But perhaps,' she says, 'we were wrong to imagine that freedom, or adventure, or happiness, was the point.'", "می‌گوید: «اما شاید اشتباه می‌کردیم که تصور می‌کردیم آزادی، یا ماجراجویی، یا خوشبختی هدف است.»"),
            StoryParagraph("'Perhaps the point,' she says, 'is simply to love, and to be loved, for as long as we can.'", "می‌گوید: «شاید هدف، تنها دوست داشتن باشد و دوست داشته شدن، تا زمانی که می‌توانیم.»"),
            StoryParagraph("This is the message of the novel: that love, not freedom, not adventure, not happiness, is the meaning of life.", "این پیام رمان است: که عشق، نه آزادی، نه ماجراجویی، نه خوشبختی، معنای زندگی است."),
            StoryParagraph("And that love, even when it ends in loss, even when it ends in death, is still worth having, still worth fighting for, still worth everything.", "و آن عشق، حتی وقتی به فقدان ختم می‌شود، حتی وقتی به مرگ ختم می‌شود، هنوز ارزش داشتن دارد، هنوز ارزش جنگیدن، هنوز ارزش همه چیز."),
            StoryParagraph("Never Let Me Go is a sad novel, but it is not a depressing one; it is a novel about loss, but also about the beauty that can exist in the midst of loss.", "هرگز رهایم مکن رمانی اندوهناک است، اما افسرده‌کننده نیست؛ رمانی درباره فقدان است، اما همچنین درباره زیبایی که می‌تواند در میان فقدان وجود داشته باشد."),
            StoryParagraph("It is a novel about death, but also about life; about what we lose, but also about what we keep.", "رمانی درباره مرگ است، اما همچنین درباره زندگی؛ درباره آنچه از دست می‌دهیم، اما همچنین درباره آنچه نگه می‌داریم."),
            StoryParagraph("And what we keep, in the end, is not our bodies, not our achievements, not our possessions, but our love.", "و آنچه در پایان نگه می‌داریم، بدن‌هایمان نیست، نه دستاوردهایمان، نه دارایی‌هایمان، بلکه عشقمان است."),
            StoryParagraph("And that love, the novel suggests, is enough; that love, the novel insists, is everything.", "و آن عشق، رمان پیشنهاد می‌دهد، کافی است؛ آن عشق، رمان اصرار می‌کند، همه چیز است."),
            StoryParagraph("Ishiguro wrote the novel in the first person, in the voice of Kathy, and this choice is crucial to the novel's effect.", "ایشی‌گورو رمان را به اول شخص نوشت، با صدای کتی و این انتخاب برای تأثیر رمان حیاتی است."),
            StoryParagraph("We are inside Kathy's mind; we see the world through her eyes; we feel what she feels; we understand what she understands.", "داخل ذهن کتی هستیم؛ جهان را از چشمانش می‌بینیم؛ آنچه حس می‌کند حس می‌کنیم؛ آنچه می‌فهمد می‌فهمیم."),
            StoryParagraph("And Kathy is not an angry narrator; she is not a rebellious one; she accepts her fate, and she tells her story with a kind of peace.", "و کتی راوی عصبانی نیست؛ راوی شورشی نیست؛ سرنوشتش را می‌پذیرد و داستانش را با نوعی آرامش تعریف می‌کند."),
            StoryParagraph("This acceptance is what makes the novel so devastating; if Kathy had raged, we could have dismissed her as a victim.", "این پذیرش همان چیزی است که رمان را اینقدر ویران‌کننده می‌کند؛ اگر کتی خشم می‌کرد، می‌توانستیم او را همچون قربانی کنار بگذاریم."),
            StoryParagraph("But her quiet dignity forces us to confront the horror of her situation, and to ask ourselves what we would do in her place.", "اما وقار آرامش ما را وادار می‌کند با هولناکی موقعیتش روبرو شویم و از خودمان بپرسیم در جای او چه می‌کردیم."),
            StoryParagraph("The novel does not offer easy answers; it does not tell us how to live; it simply shows us one way, one possibility, one response to the absurdity of existence.", "رمان پاسخ‌های آسان ارائه نمی‌دهد؛ به ما نمی‌گوید چگونه زندگی کنیم؛ تنها یک راه را نشانمان می‌دهد، یک امکان، یک پاسخ به پوچی وجود."),
            StoryParagraph("And that response, that way of being, is love; not sentimental love, not romantic love, but the deep, enduring love that binds human beings to each other, that gives meaning to our brief and beautiful lives.", "و آن پاسخ، آن شیوه بودن، عشق است؛ نه عشق احساساتی، نه عشق رمانتیک، بلکه عشق عمیق و پایدار که انسان‌ها را به هم می‌بندد، که به زندگی‌های کوتاه و زیبایمان معنا می‌دهد."),
            StoryParagraph("Never Let Me Go is not a novel to be enjoyed; it is a novel to be experienced, to be suffered, to be lived.", "هرگز رهایم مکن رمانی نیست که لذت برده شود؛ رمانی است که تجربه شود، رنج کشیده شود، زندگی شود."),
            StoryParagraph("And once you have experienced it, once you have suffered with Kathy and Tommy and Ruth, you are changed.", "و یک بار که تجربه‌اش کرده باشی، یک بار که با کتی و تامی و راث رنج کشیده باشی، تغییر کرده‌ای."),
            StoryParagraph("For the novel shows us something that we have always known but have been afraid to face: that our lives are short, that our deaths are certain, and that love is the only thing that matters.", "زیرا رمان چیزی را نشانمان می‌دهد که همیشه می‌دانستیم اما می‌ترسیدیم با آن روبرو شویم: که زندگی‌هایمان کوتاه است، که مرگ‌هایمان حتمی است و عشق تنها چیزی است که اهمیت دارد."),
            StoryParagraph("And in showing us this, in forcing us to face this, it gives us a gift: the gift of knowing how to live.", "و در نشان دادن این، در وادار کردنمان به رویارویی با این، هدیه‌ای به ما می‌دهد: هدیه دانستن چگونه زندگی کنیم."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story that ends is not the story that ends; it is the story that begins again, in every reader, in every heart, in every life.", "زیرا داستانی که تمام می‌شود همان داستانی نیست که تمام می‌شود؛ داستانی است که دوباره آغاز می‌شود، در هر خواننده، در هر قلب، در هر زندگی."),
            StoryParagraph("Never let me go, Kathy whispers, in the darkness, and the words echo across the years, across the fields, across the distance between us.", "هرگز رهایم مکن، کتی در تاریکی زمزمه می‌کند و کلمات در طول سال‌ها پژواک می‌کنند، در طول مزارع، در طول فاصله میان ما."),
            StoryParagraph("Never let me go, she whispers, and we hear her, and we understand, and we hold on.", "هرگز رهایم مکن، زمزمه می‌کند و ما می‌شنویمش و می‌فهمیم و نگه می‌داریم."),
            StoryParagraph("Never let me go.", "هرگز رهایم مکن.")
        )
    )
}